{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.2"
    }
  ],
  "source_path": "/accounts/{AccountId}/statements",
  "operations": {
    "get": {
      "tags": [
        "Statements"
      ],
      "summary": "Get Statements",
      "description": "The following permissions are applicable to this resource:\n* ReadStatements\nRefer to the Permissions and Data Clusters section of the Customer Data page for further information.\nStatements MUST be returned in descending `OpeningDate` order, newest first. Where two statements share the same `OpeningDate`, `StatementId` SHOULD be used as a descending tiebreaker so that the ordering is stable.\nOrdering is applied to the filtered result set before pagination, so the first page always contains the most recent statements matching the request. The `fromStatementDate` and `toStatementDate` parameters filter the result set, they do not change its order.\nNo sort control is offered: a TPP cannot request ascending order.\n",
      "operationId": "GetAccountAccountIdStatements",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/AccountId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "in": "query",
          "name": "fromStatementDate",
          "description": "Start date for filtering of the Statements on the Statements.OpeningDate field. If this is not populated, the start date will be open ended",
          "schema": {
            "type": "string",
            "format": "date"
          }
        },
        {
          "in": "query",
          "name": "toStatementDate",
          "description": "End date for filtering of the Statements on the Statement.OpeningDate.  If this is not populated, the end date will be open ended",
          "schema": {
            "type": "string",
            "format": "date"
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Return statements",
          "content": {
            "application/json; charset=utf-8": {
              "schema": {
                "$ref": "#/components/schemas/AEReadStatements"
              }
            },
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/AEReadStatements"
              }
            },
            "application/jwt": {
              "schema": {
                "$ref": "#/components/schemas/AEReadStatementsSigned"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "name": "AccountId",
  "in": "path",
  "description": "AccountId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "description": "List of Statements for an Account",
  "type": "object",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "$ref": "#/components/schemas/AEStatements"
    },
    "Links": {
      "$ref": "#/components/schemas/Links"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTransactionsStatements"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "AccountId",
    "AccountSubType",
    "Statements"
  ],
  "properties": {
    "AccountId": {
      "description": "\r\nA unique and immutable identifier produced by the LFI to identify the account resource.This identifier has no meaning to the account owner.",
      "type": "string"
    },
    "AccountSubType": {
      "$ref": "#/components/schemas/AEBankDataSharing.AEExternalAccountSubTypeCode"
    },
    "Statements": {
      "description": "Array containing details of periodic statements. Each statement includes key financial metrics, balances, summaries, and payment details for a specific statement cycle",
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "StatementId",
          "StatementDate",
          "OpeningDate",
          "ClosingDate",
          "OpeningBalance",
          "ClosingBalance",
          "Summary"
        ],
        "properties": {
          "StatementId": {
            "description": "Unique identifier/reference for the statement",
            "type": "string"
          },
          "StatementDate": {
            "description": "Date the statement was issued/generated",
            "type": "string",
            "format": "date"
          },
          "OpeningDate": {
            "description": "Start date of the statement period",
            "type": "string",
            "format": "date"
          },
          "ClosingDate": {
            "description": "End date of the statement period",
            "type": "string",
            "format": "date"
          },
          "CreditLine": {
            "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
          },
          "OpeningBalance": {
            "allOf": [
              {
                "description": "Object containing opening balance details",
                "type": "object",
                "required": [
                  "CreditDebitIndicator"
                ],
                "properties": {
                  "CreditDebitIndicator": {
                    "description": "Indicates whether the closing balance is a credit or a debit",
                    "type": "string",
                    "enum": [
                      "Credit",
                      "Debit"
                    ]
                  }
                }
              },
              {
                "$ref": "#/components/schemas/AEBalanceWithCategorization"
              }
            ]
          },
          "ClosingBalance": {
            "allOf": [
              {
                "description": "Object containing closing balance details",
                "type": "object",
                "required": [
                  "CreditDebitIndicator"
                ],
                "properties": {
                  "CreditDebitIndicator": {
                    "description": "Indicates whether the closing balance is a credit or a debit",
                    "type": "string",
                    "enum": [
                      "Credit",
                      "Debit"
                    ]
                  }
                }
              },
              {
                "$ref": "#/components/schemas/AEBalanceWithCategorization"
              }
            ]
          },
          "Summary": {
            "description": "Array providing an aggregated summary of financial activities within the statement period, such as Purchase, Repayments, Fee, and Interest/Profit. Each object contains the total aggregated amount, currency, and the count of transactions for the corresponding SubTransactionType.",
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "CreditDebitIndicator",
                "SubTransactionType",
                "Amount",
                "Count"
              ],
              "properties": {
                "CreditDebitIndicator": {
                  "description": "Indicates whether the summarized activity is a credit or a debit",
                  "type": "string",
                  "enum": [
                    "Credit",
                    "Debit"
                  ]
                },
                "TransactionType": {
                  "description": "Type of transaction activity.",
                  "type": "string",
                  "enum": [
                    "POS",
                    "ECommerce",
                    "ATM",
                    "BillPayments",
                    "LocalBankTransfer",
                    "SameBankTransfer",
                    "InternationalTransfer",
                    "Teller",
                    "Cheque",
                    "Other"
                  ]
                },
                "SubTransactionType": {
                  "$ref": "#/components/schemas/AESubTransactionType"
                },
                "Amount": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "Count": {
                  "description": "Number of transactions or occurrences for the transaction type",
                  "type": "number"
                }
              }
            }
          },
          "ExpectedNextStatement": {
            "description": "Object containing projected finance charges or fees expected in the next statement cycle.",
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "minProperties": 1,
              "properties": {
                "Type": {
                  "description": "Statement type.",
                  "type": "string",
                  "enum": [
                    "Purchase",
                    "Reversal",
                    "Refund",
                    "Withdrawal",
                    "WithdrawalReversal",
                    "Deposit",
                    "DepositReversal",
                    "MoneyTransfer",
                    "Repayments",
                    "Interest",
                    "Fee",
                    "Charges",
                    "Profit",
                    "Disbursement",
                    "Adjustment",
                    "Tax",
                    "Rewards",
                    "NotApplicable"
                  ]
                },
                "Amount": {
                  "description": "Statement amount, according to `Type` value.",
                  "type": "object",
                  "required": [
                    "Amount",
                    "Currency"
                  ],
                  "properties": {
                    "Amount": {
                      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
                    },
                    "Currency": {
                      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
                    }
                  }
                }
              }
            }
          },
          "NextPayment": {
            "description": "Object containing details related to the next payment due",
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "Date",
                "Amount"
              ],
              "properties": {
                "Date": {
                  "description": "Payment due date",
                  "type": "string",
                  "format": "date"
                },
                "Amount": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "Type": {
                  "description": "Type of payment - minimum, scheduled, estimated, or other",
                  "type": "string",
                  "enum": [
                    "Minimum",
                    "Scheduled",
                    "Estimated",
                    "Other"
                  ]
                }
              }
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "description": "This is the value of the last direct debit collection from the User 1 account.",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
    },
    "Currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
    }
  },
  "additionalProperties": false
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "required": [
    "Amount"
  ],
  "properties": {
    "Amount": {
      "description": "The value of the balance on account, incorporating `Amount` and `Currency`.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      }
    },
    "Components": {
      "description": "Components of the stated balance, defined by the value of `BalanceCategory`, that reflects a portion of the stated balance.",
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/components/schemas/AEAmountWithCategorization"
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "BalanceCategory",
    "Amount"
  ],
  "properties": {
    "BalanceCategory": {
      "$ref": "#/components/schemas/AEBalanceCategory"
    },
    "BalanceDescription": {
      "description": "Allows a description to provided of the balance to identify the specific Shari’ah compliant charges, payments, and rewards made which can affect the balance.",
      "type": "string",
      "minLength": 1,
      "maxLength": 500
    },
    "Amount": {
      "description": "The value of the categorized balance, incorporating `Amount` and `Currency`.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      }
    }
  }
}

